package br.com.conectatea.crianca.api; import br.com.conectatea.auditoria.application.AuditLogService; import br.com.conectatea.crianca.domain.*; import br.com.conectatea.crianca.infrastructure.*; import br.com.conectatea.security.AuthenticatedUser; import br.com.conectatea.shared.domain.BusinessRuleException; import br.com.conectatea.vinculo.domain.*; import br.com.conectatea.vinculo.infrastructure.VinculoResponsavelRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.Instant; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/criancas/{id}") @io.swagger.v3.oas.annotations.tags.Tag(name="Crianças") public class GestaoCriancaController{private final CriancaRepository children;private final VinculoResponsavelRepository links;private final HistoricoCriancaRepository history;private final AuditLogService audits;public GestaoCriancaController(CriancaRepository c,VinculoResponsavelRepository l,HistoricoCriancaRepository h,AuditLogService a){children=c;links=l;history=h;audits=a;}
@PatchMapping("/estado")@Transactional public StateResponse status(Authentication auth,@PathVariable Long id,@Valid @RequestBody StateRequest request){var actor=manager(auth,id);var child=children.findById(id).orElseThrow();var old=child.getStatusAcompanhamento();child.alterarStatus(request.status(),actor.id(),request.motivo(),Instant.now());history.save(new HistoricoCrianca(id,actor.id(),"ESTADO_ALTERADO",old.name(),request.status().name(),request.motivo()));audits.record(actor.id(),"ESTADO_CRIANCA_ALTERADO","CRIANCA",id,id,null,"SUCESSO","de="+old+";para="+request.status());return new StateResponse(id,request.status(),child.isArquivada());}
@PatchMapping("/arquivamento")@Transactional public StateResponse archive(Authentication auth,@PathVariable Long id,@Valid @RequestBody ArchiveRequest request){var actor=manager(auth,id);var child=children.findById(id).orElseThrow();if(request.arquivada())child.arquivar();else child.reativar();history.save(new HistoricoCrianca(id,actor.id(),request.arquivada()?"ARQUIVADA":"REATIVADA",Boolean.toString(!request.arquivada()),Boolean.toString(request.arquivada()),request.motivo()));audits.record(actor.id(),request.arquivada()?"CRIANCA_ARQUIVADA":"CRIANCA_REATIVADA","CRIANCA",id,id,null,"SUCESSO",null);return new StateResponse(id,child.getStatusAcompanhamento(),child.isArquivada());}
private AuthenticatedUser manager(Authentication auth,Long id){var a=(AuthenticatedUser)auth.getPrincipal();if(!links.existsByResponsavelIdAndCriancaIdAndStatusAndPapel(a.id(),id,StatusVinculo.VINCULADO,PapelCirculo.RESPONSAVEL_GESTOR))throw new AccessDeniedException("Somente gestor altera estado ou arquivamento");return a;}public record StateRequest(@NotNull StatusAcompanhamento status,@NotBlank @Size(max=500)String motivo){}public record ArchiveRequest(boolean arquivada,@NotBlank @Size(max=500)String motivo){}public record StateResponse(Long criancaId,StatusAcompanhamento status,boolean arquivada){}
}
